package org.thesis.eval;

import com.github.javaparser.*;import com.github.javaparser.ast.*;import com.github.javaparser.ast.body.*;import com.github.javaparser.ast.expr.*;import com.github.javaparser.symbolsolver.JavaSymbolSolver;import com.github.javaparser.symbolsolver.resolution.typesolvers.*;
import java.nio.file.*;import java.util.*;

final class SourceIndex {
 final Path repo; final JavaParser parser; final boolean hasMaven; final boolean hasGradle; final Map<String,TypeDeclaration<?>> types=new HashMap<>(); final Map<String,Path> typeFiles=new HashMap<>(); final Map<String,List<MethodDeclaration>> methods=new HashMap<>(); final Map<String,List<ConstructorDeclaration>> ctors=new HashMap<>(); final Map<String,FieldDeclaration> fields=new HashMap<>(); final List<String> diagnostics=new ArrayList<>();
 SourceIndex(Path repo)throws Exception{this.repo=repo;this.hasMaven=hasFile(repo,"pom.xml");this.hasGradle=hasAny(repo,List.of("build.gradle","build.gradle.kts","settings.gradle","settings.gradle.kts"));CombinedTypeSolver solver=new CombinedTypeSolver();solver.add(new ReflectionTypeSolver());for(Path root:sourceRoots(repo)){try{solver.add(new JavaParserTypeSolver(root));}catch(Exception e){diagnostics.add("TypeSolver root failed: "+root+" : "+e.getMessage());}}ParserConfiguration pc=new ParserConfiguration().setLanguageLevel(ParserConfiguration.LanguageLevel.BLEEDING_EDGE).setSymbolResolver(new JavaSymbolSolver(solver));parser=new JavaParser(pc);build();}
 private void build()throws Exception{try(var s=Files.walk(repo)){for(Path p:s.filter(x->x.toString().endsWith(".java")).filter(x->!x.toString().contains(FileSystems.getDefault().getSeparator()+"target"+FileSystems.getDefault().getSeparator())).toList()){try{CompilationUnit cu=parser.parse(p).getResult().orElse(null);if(cu==null)continue;String pkg=cu.getPackageDeclaration().map(x->x.getNameAsString()+".").orElse("");for(TypeDeclaration<?> t:cu.getTypes())indexType(pkg,t,p,null);}catch(Exception e){diagnostics.add("Parse failed "+repo.relativize(p)+": "+shortMsg(e));}}}}
 private void indexType(String prefix,TypeDeclaration<?> t,Path file,String parent){String fqn=parent==null?prefix+t.getNameAsString():parent+"."+t.getNameAsString();types.putIfAbsent(fqn,t);typeFiles.putIfAbsent(fqn,file);for(MethodDeclaration m:t.getMethods())methods.computeIfAbsent(fqn+"#"+m.getNameAsString()+"/"+m.getParameters().size(),k->new ArrayList<>()).add(m);for(ConstructorDeclaration c:t.getConstructors())ctors.computeIfAbsent(fqn+"#<init>/"+c.getParameters().size(),k->new ArrayList<>()).add(c);for(FieldDeclaration f:t.getFields())for(VariableDeclarator v:f.getVariables())fields.putIfAbsent(fqn+"#"+v.getNameAsString(),f);for(BodyDeclaration<?> b:t.getMembers())if(b instanceof TypeDeclaration<?> nt)indexType(prefix,nt,file,fqn);}
 Optional<MethodDeclaration> method(String owner,String name,int arity){List<MethodDeclaration>x=methods.get(owner+"#"+name+"/"+arity);return x==null||x.isEmpty()?Optional.empty():Optional.of(x.get(0));}
 Optional<ConstructorDeclaration> ctor(String owner,int arity){List<ConstructorDeclaration>x=ctors.get(owner+"#<init>/"+arity);return x==null||x.isEmpty()?Optional.empty():Optional.of(x.get(0));}
 Optional<FieldDeclaration> field(String owner,String name){return Optional.ofNullable(fields.get(owner+"#"+name));}
 boolean isRepository(String fqn){if(fqn==null)return false;String raw=raw(fqn);return types.containsKey(raw);}
 Path fileOf(String owner){return typeFiles.get(raw(owner));}
 String sourceOf(String owner){Path p=fileOf(owner);return p==null?"":repo.relativize(p).toString().replace('\\','/');}
 String fqnFor(TypeDeclaration<?> t){for(var e:types.entrySet())if(e.getValue()==t)return e.getKey();return t.getNameAsString();}
 static String raw(String s){if(s==null)return "";int g=s.indexOf('<');if(g>=0)s=s.substring(0,g);while(s.endsWith("[]"))s=s.substring(0,s.length()-2);return s.replace('$','.');}
 static List<Path> sourceRoots(Path repo)throws Exception{LinkedHashSet<Path> roots=new LinkedHashSet<>();try(var s=Files.walk(repo,7)){for(Path p:s.filter(Files::isDirectory).toList()){String q=p.toString().replace('\\','/');if(q.endsWith("/src/main/java")||q.endsWith("/src/test/java")||q.endsWith("/src/java")||q.endsWith("/source")||q.endsWith("/src"))roots.add(p);}}if(roots.isEmpty())roots.add(repo);return new ArrayList<>(roots);}
 static boolean hasFile(Path repo,String name){try(var s=Files.walk(repo,5)){return s.anyMatch(p->p.getFileName().toString().equals(name));}catch(Exception e){return false;}}
 static boolean hasAny(Path repo,List<String> names){try(var s=Files.walk(repo,5)){return s.anyMatch(p->names.contains(p.getFileName().toString()));}catch(Exception e){return false;}}
 static String shortMsg(Throwable e){String s=e.getMessage();if(s==null)s=e.getClass().getSimpleName();return s.length()>250?s.substring(0,250):s;}
}
